import sys
from collections import Counter

def min_window_brute(s, t):
    need = Counter(t)
    best = None
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            sub = s[i:j]
            if all(sub.count(c) >= need[c] for c in need):
                if best is None or len(sub) < len(best):
                    best = sub
    return best or ''

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    s, t = data[0], data[1]
    print(min_window_brute(s, t))

import sys
from collections import Counter

def min_window_opt(s, t):
    need = Counter(t)
    have = Counter()
    need_cnt = len(need)
    have_cnt = 0
    left = 0
    best = None
    for right, ch in enumerate(s):
        if ch in need:
            have[ch] += 1
            if have[ch] == need[ch]:
                have_cnt += 1
        while have_cnt == need_cnt:
            if best is None or right - left + 1 < len(best):
                best = s[left:right + 1]
            lc = s[left]
            if lc in need:
                have[lc] -= 1
                if have[lc] < need[lc]:
                    have_cnt -= 1
            left += 1
    return best or ''

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    s, t = data[0], data[1]
    print(min_window_opt(s, t))
